SELECT COUNT(*) AS total_mismatch, SUM(CASE WHEN d.id IS NULL THEN 1 ELSE 0 END) AS missing_in_dev, SUM(CASE WHEN p.amount IS NULL OR d.amount IS NULL THEN 1 ELSE 0 END) AS null_amounts FROM prod.orders p LEFT JOIN db.orders d ON p.id = d.id WHERE d.id IS NULL OR p.amount <> d.amount OR (p.amount IS NULL) <> (d.amount IS NULL);
SELECT COUNT(*) AS dev_ids_not_in_prod FROM db.orders d LEFT JOIN prod.orders p ON p.id=d.id WHERE p.id IS NULL;
SELECT COUNT(*) n, COUNT(DISTINCT id) d FROM db.orders;
SELECT COUNT(*) n, COUNT(DISTINCT id) d FROM prod.orders

